# SIAMS-ALPHA-M1: generated by setup-alpha-apps.sh, safe to edit (re-runs skip it)
"""Placement factories. Team Beta: use ApprovedPlacementFactory to build logbook tests
before the placement APIs are used end to end. Dates are relative to today, so the
placement is always "open" now."""

from datetime import date, timedelta

import factory
from django.utils import timezone
from factory.django import DjangoModelFactory

from apps.accounts.tests.factories import (
    AcademicSupervisorFactory,
    StudentFactory,
    WorkplaceSupervisorFactory,
)


class PeriodFactory(DjangoModelFactory):
    class Meta:
        model = "placements.InternshipPeriod"

    name = factory.Sequence(lambda n: f"Period {n}")
    type = "ATTACHMENT"
    start_date = factory.LazyFunction(lambda: date.today() - timedelta(days=30))
    end_date = factory.LazyFunction(lambda: date.today() + timedelta(days=120))
    required_hours = 400
    min_visits = 2
    assessment_opens_on = None


class OrganizationFactory(DjangoModelFactory):
    class Meta:
        model = "placements.Organization"

    name = factory.Sequence(lambda n: f"Acme Ltd {n}")
    address = "1 Industrial Road"
    county = "Nairobi"
    contact_email = factory.Sequence(lambda n: f"hr{n}@acme.example")
    contact_phone = "+254700000000"
    is_verified = True


class PlacementFactory(DjangoModelFactory):
    """A complete DRAFT placement."""

    class Meta:
        model = "placements.Placement"

    student = factory.SubFactory(StudentFactory)
    period = factory.SubFactory(PeriodFactory)
    organization = factory.SubFactory(OrganizationFactory)
    status = "DRAFT"
    role_title = "Software Intern"
    department = "IT"
    task_description = "Build and test internal tools."
    start_date = factory.LazyAttribute(lambda o: o.period.start_date + timedelta(days=7))
    end_date = factory.LazyAttribute(lambda o: o.period.end_date - timedelta(days=7))
    proposed_supervisor_name = "Jane Mentor"
    proposed_supervisor_email = factory.Sequence(lambda n: f"mentor{n}@acme.example")
    proposed_supervisor_phone = "+254711111111"


class SubmittedPlacementFactory(PlacementFactory):
    status = "SUBMITTED"
    submitted_at = factory.LazyFunction(timezone.now)


class ApprovedPlacementFactory(SubmittedPlacementFactory):
    """APPROVED with both supervisors, ready for logbook entries."""

    status = "APPROVED"
    academic_supervisor = factory.SubFactory(AcademicSupervisorFactory)
    workplace_supervisor = factory.SubFactory(WorkplaceSupervisorFactory)
    decided_at = factory.LazyFunction(timezone.now)
